input.command:
tail -n +2 /app/data/test_center_logs.csv | cut -d',' -f20 | sed 's/"//g' | awk '{
  gsub(/[\/&;，,+、]/, "\n")
  for (i = 1; i <= NF; i++) {
    if ($i != "") count[NR]++
  }
}
END {
  for (c in count) {
    segments[count[c]]++
  }
  for (s in segments) {
    print s ": " segments[s]
  }
}' | sort -n
